from abc import ABCMeta, abstractmethod
import six


@six.add_metaclass(ABCMeta)
class Preparing:

    def __init__(self, collector=None, **kwargs):
        super(Preparing, self).__init__(**kwargs)
        self._collector = collector

    @property
    def collector(self):
        return self._collector

    def __getattr__(self, name):
        if self._collector is not None and hasattr(self._collector, name):
            return getattr(self._collector, name)
        else:
            raise AttributeError(
                f"'{self.__class__.__name__}' object has no attribute '{name}'")

    def _collect(self, target_dir):
        self._collector._collect(target_dir=target_dir)

    def _start(self):
        if hasattr(self._collector, '_start'):
            self._collector._start()
        else:
            self._collector.start()

    def _stop(self):
        if hasattr(self._collector, '_stop'):
            self._collector._stop()
        else:
            self._collector.stop()

    def setup(self, group=None):
        self._pre_setup()
        self._collector.setup(group=group)

    def teardown(self, group=None, force=False):
        self._collector.teardown(group=group, force=force)
        self._post_teardown()

    @abstractmethod
    def _pre_setup(self):
        pass

    def _post_teardown(self):
        pass
